___CSS_LOADER_EXPORT___.push([module.id, "\n.font-custom{\n    font-size:15px !important\n}\n", "",{"version":3,"sources":["webpack://./modules/Report/Resources/assets/js/components/DataTableCash.vue"],"names":[],"mappings":";AAuEA;IACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"row\">\n\n            <div class=\"col-md-12 col-lg-12 col-xl-12 \">\n                  \n                <div class=\"row mt-2\">  \n                        \n                        <div class=\"col-md-5\">\n                            <div class=\"form-group\">\n                                <label class=\"control-label\">Usuario / Vendedor</label>\n                                <el-select v-model=\"form.user_id\" clearable filterable>\n                                    <el-option v-for=\"option in users\" :key=\"option.id\" :value=\"option.id\" :label=\"option.name\"></el-option>\n                                </el-select>\n                            </div>\n                        </div>\n                        <div class=\"col-md-5\">\n                            <div class=\"form-group\">\n                                <label class=\"control-label\">Tipo de documento</label>\n                                <el-select v-model=\"form.document_type_id\" >\n                                    <el-option v-for=\"option in document_types\" :key=\"option.id\" :value=\"option.id\" :label=\"option.description\"></el-option>\n                                </el-select>\n                            </div>\n                        </div>\n\n                        <div class=\"col-lg-9 col-md-9 col-md-9 col-sm-12\" style=\"margin-top:29px\"> \n                            <el-button class=\"submit\" type=\"primary\" @click.prevent=\"getRecordsByFilter\" :loading=\"loading_submit\" icon=\"el-icon-search\" >Buscar</el-button>\n                            \n                            <template v-if=\"records.length>0\"> \n\n                                <el-button class=\"submit\" type=\"danger\"  icon=\"el-icon-tickets\" @click.prevent=\"clickDownload('pdf')\" >Exportar PDF</el-button>\n\n                                <el-button class=\"submit\" type=\"success\" @click.prevent=\"clickDownload('excel')\"><i class=\"fa fa-file-excel\" ></i>  Exportal Excel</el-button>\n\n                            </template>\n\n                        </div>             \n                    \n                </div>\n                <div class=\"row mt-1 mb-4\">\n                    \n                </div> \n            </div>\n\n\n            <div class=\"col-md-12\">\n                <div class=\"table-responsive\">\n                    <table class=\"table\">\n                        <thead>\n                        <slot name=\"heading\"></slot>\n                        </thead>\n                        <tbody>\n                            <slot v-for=\"(row, index) in records\" :row=\"row\" :index=\"customIndex(index)\"></slot>\n                        </tbody> \n                    </table>\n                    <div>\n                        <el-pagination\n                                @current-change=\"getRecords\"\n                                layout=\"total, prev, pager, next\"\n                                :total=\"pagination.total\"\n                                :current-page.sync=\"pagination.current_page\"\n                                :page-size=\"pagination.per_page\">\n                        </el-pagination>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</template>\n<style>\n.font-custom{\n    font-size:15px !important\n}\n</style>\n<script>\n\n    import moment from 'moment'\n    import queryString from 'query-string'\n\n    export default { \n        props: {\n            resource: String,\n        },\n        data () {\n            return {\n                loading_submit:false,\n                columns: [],\n                records: [],\n                headers: headers_token,\n                document_types: [],\n                pagination: {}, \n                search: {}, \n                totals: {}, \n                establishment: null,\n                users: [],       \n                form: {}, \n            }\n        },\n        computed: {\n        },\n        created() {\n            this.initForm()\n            this.$eventHub.$on('reloadData', () => {\n                this.getRecords()\n            })\n        },\n        async mounted () { \n\n            await this.$http.get(`/${this.resource}/filter`)\n                .then(response => {\n                    this.document_types = response.data.document_types;\n                    this.users = response.data.users;\n                });\n\n\n            await this.getRecords()\n\n        },\n        methods: {  \n            clickDownload(type) {                 \n                let query = queryString.stringify({\n                    ...this.form\n                });\n                window.open(`/${this.resource}/${type}/?${query}`, '_blank');\n            },\n            initForm(){\n \n                this.form = {\n                    document_type_id:'01',\n                    user_id:null,\n                }\n\n            },  \n            customIndex(index) {\n                return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n            }, \n            async getRecordsByFilter(){\n\n                this.loading_submit = await true\n                await this.getRecords()\n                this.loading_submit = await false\n\n            },\n            getRecords() {\n                return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n                    this.records = response.data.data\n                    this.pagination = response.data.meta\n                    this.pagination.per_page = parseInt(response.data.meta.per_page)\n                    this.loading_submit = false\n                });\n\n\n            },\n            getQueryParameters() {\n                return queryString.stringify({\n                    page: this.pagination.current_page,\n                    limit: this.limit,\n                    ...this.form\n                })\n            },\n             \n        }\n    }\n</script>"],"sourceRoot":""}]);
