___CSS_LOADER_EXPORT___.push([module.id, "\n.font-custom{\n    font-size:15px !important\n}\n", "",{"version":3,"sources":["webpack://./modules/Report/Resources/assets/js/components/DataTablePeriods.vue"],"names":[],"mappings":";AAqGA;IACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"btn-filter-content\">\n            <el-button\n                type=\"secondary\"\n                class=\"btn-show-filter\"\n                :class=\"{ shift: isVisible }\"\n                @click=\"toggleInformation\"\n            >\n                {{ isVisible ? \"Ocultar filtros\" : \"Mostrar filtros\" }}\n            </el-button>\n        </div>\n        <div class=\"row\">\n\n            <div class=\"col-md-12 col-lg-12 col-xl-12 \" v-if=\"isVisible\">\n\n                <div class=\"row mt-2\">\n\n                    <div class=\"col-md-3 form-modern\">\n                        <label class=\"control-label\">Periodo</label>\n                        <el-select v-model=\"form.period\" @change=\"changePeriod\">\n                            <el-option key=\"month\" value=\"month\" label=\"Por mes\"></el-option>\n                            <el-option key=\"between_months\" value=\"between_months\" label=\"Entre meses\"></el-option>\n                            <el-option key=\"date\" value=\"date\" label=\"Por fecha\"></el-option>\n                            <el-option key=\"between_dates\" value=\"between_dates\" label=\"Entre fechas\"></el-option>\n                        </el-select>\n                    </div>\n                    <template v-if=\"form.period === 'month' || form.period === 'between_months'\">\n                        <div class=\"col-md-3 form-modern\">\n                            <label class=\"control-label\">Mes de</label>\n                            <el-date-picker v-model=\"form.month_start\" type=\"month\"\n                                            @change=\"changeDisabledMonths\"\n                                            value-format=\"yyyy-MM\" format=\"MM/yyyy\" :clearable=\"false\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_months'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Mes al</label>\n                            <el-date-picker v-model=\"form.month_end\" type=\"month\"\n                                            :picker-options=\"pickerOptionsMonths\"\n                                            value-format=\"yyyy-MM\" format=\"MM/yyyy\" :clearable=\"false\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'date' || form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha del</label>\n                            <el-date-picker v-model=\"form.date_start\" type=\"date\"\n                                            @change=\"changeDisabledDates\"\n                                            value-format=\"yyyy-MM-dd\" format=\"dd/MM/yyyy\" :clearable=\"false\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha al</label>\n                            <el-date-picker v-model=\"form.date_end\" type=\"date\"\n                                            :picker-options=\"pickerOptionsDates\"\n                                            value-format=\"yyyy-MM-dd\" format=\"dd/MM/yyyy\" :clearable=\"false\"></el-date-picker>\n                        </div>\n                    </template>\n\n                </div>\n                <div class=\"row\">\n                    \n                    <div class=\"col-lg-7 col-md-7 col-md-7 col-sm-12\" style=\"margin-top:29px\">\n                        <el-button class=\"submit\" type=\"primary\" @click.prevent=\"getRecordsByFilter\" :loading=\"loading_submit\" icon=\"el-icon-search\" >Buscar</el-button>\n\n                        <template v-if=\"records.length>0\">\n\n                            <el-button class=\"submit\" type=\"success\" @click.prevent=\"clickDownload('excel')\"><i class=\"fa fa-file-excel\" ></i>  Exportal Excel</el-button>\n                            <el-button class=\"submit\" type=\"danger\"  icon=\"el-icon-tickets\" @click.prevent=\"clickDownload('pdf')\" >Exportar PDF</el-button>\n\n                        </template>\n                    </div>\n\n                </div>\n            </div>\n            <div class=\"col-md-12 mt-2\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                        <thead>\n                        <slot name=\"heading\"></slot>\n                        </thead>\n                        <tbody>\n                            <slot v-for=\"(row, index) in records\" :row=\"row\" :index=\"customIndex(index)\"></slot>\n                        </tbody>\n                    </table>\n                </div>\n                <el-pagination\n                        @current-change=\"getRecords\"\n                        layout=\"total, prev, pager, next\"\n                        :total=\"pagination.total\"\n                        :current-page.sync=\"pagination.current_page\"\n                        :page-size=\"pagination.per_page\">\n                </el-pagination>\n            </div>\n        </div>\n    </div>\n</template>\n<style>\n.font-custom{\n    font-size:15px !important\n}\n</style>\n<script>\n\n    import moment from 'moment'\n    import queryString from 'query-string'\n\n    export default {\n        props: {\n            resource: String,\n        },\n        data () {\n            return {\n                isVisible: false,\n                config:{},\n                loading_submit:false,\n                columns: [],\n                records: [],\n                headers: headers_token,\n                pagination: {},\n                search: {},\n                form: {},\n                pickerOptionsDates: {\n                    disabledDate: (time) => {\n                        time = moment(time).format('YYYY-MM-DD')\n                        return this.form.date_start > time\n                    }\n                },\n                pickerOptionsMonths: {\n                    disabledDate: (time) => {\n                        time = moment(time).format('YYYY-MM')\n                        return this.form.month_start > time\n                    }\n                },\n                loading_search:false,\n                showLeftShadow: false,\n                showRightShadow: false,\n            }\n        },\n        created() {\n\n            this.initForm()\n            this.$eventHub.$on('reloadData', () => {\n                this.getRecords()\n            })\n        },\n        async mounted () {\n            this.$nextTick(() => {\n                const el = this.$refs.scrollContainer;\n                if (el) {\n                    el.addEventListener('scroll', this.checkScrollShadows);\n                    this.checkScrollShadows();\n                }\n            });\n\n        },\n        methods: {\n            checkScrollShadows() {\n                const el = this.$refs.scrollContainer;\n                if (!el) return;\n                \n                const scrollLeft = el.scrollLeft;\n                const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n                \n                this.showLeftShadow = scrollLeft > 1;\n                this.showRightShadow = scrollRight > 1;\n            },\n            toggleInformation(){\n                this.isVisible = !this.isVisible;\n            },\n            clickDownload(type) {\n                let query = queryString.stringify({\n                    ...this.form\n                });\n                window.open(`/${this.resource}/${type}/?${query}`, '_blank');\n            },\n            initForm(){\n\n                this.form = {\n                    period: 'month',\n                    date_start: moment().format('YYYY-MM-DD'),\n                    date_end: moment().format('YYYY-MM-DD'),\n                    month_start: moment().format('YYYY-MM'),\n                    month_end: moment().format('YYYY-MM'),\n                }\n\n            },\n            customIndex(index) {\n                return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n            },\n            async getRecordsByFilter(){\n\n                this.loading_submit = await true\n                await this.getRecords()\n                this.loading_submit = await false\n\n            },\n            getRecords() {\n                return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n                    this.records = response.data.data\n                    this.pagination = response.data.meta\n                    this.pagination.per_page = parseInt(response.data.meta.per_page)\n                    this.loading_submit = false\n                });\n\n\n            },\n            getQueryParameters() {\n                return queryString.stringify({\n                    page: this.pagination.current_page,\n                    limit: this.limit,\n                    ...this.form\n                })\n            },\n            changeDisabledDates() {\n                if (this.form.date_end < this.form.date_start) {\n                    this.form.date_end = this.form.date_start\n                }\n            },\n            changeDisabledMonths() {\n                if (this.form.month_end < this.form.month_start) {\n                    this.form.month_end = this.form.month_start\n                }\n            },\n            changePeriod() {\n                if(this.form.period === 'month') {\n                    this.form.month_start = moment().format('YYYY-MM');\n                    this.form.month_end = moment().format('YYYY-MM');\n                }\n                if(this.form.period === 'between_months') {\n                    this.form.month_start = moment().startOf('year').format('YYYY-MM'); \n                    this.form.month_end = moment().endOf('year').format('YYYY-MM');;\n                }\n                if(this.form.period === 'date') {\n                    this.form.date_start = moment().format('YYYY-MM-DD');\n                    this.form.date_end = moment().format('YYYY-MM-DD');\n                }\n                if(this.form.period === 'between_dates') {\n                    this.form.date_start = moment().startOf('month').format('YYYY-MM-DD');\n                    this.form.date_end = moment().endOf('month').format('YYYY-MM-DD');\n                }\n            },\n        }\n    }\n</script>\n"],"sourceRoot":""}]);
