___CSS_LOADER_EXPORT___.push([module.id, "\n.font-custom {\n    font-size: 15px !important\n}\n", "",{"version":3,"sources":["webpack://./modules/Report/Resources/assets/js/components/DataTableReportsComissionDetail.vue"],"names":[],"mappings":";AAySA;IACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"btn-filter-content\">\n            <el-button\n                type=\"secondary\"\n                class=\"btn-show-filter\"\n                :class=\"{ shift: isVisible }\"\n                @click=\"toggleInformation\"\n            >\n                {{ isVisible ? \"Ocultar filtros\" : \"Mostrar filtros\" }}\n            </el-button>\n        </div>\n        <div class=\"row\">\n\n            <div class=\"col-md-12 col-lg-12 col-xl-12 \" v-if=\"isVisible\">\n\n                <div class=\"row mt-2\">\n\n                    <div class=\"col-md-3 form-modern\">\n                        <label class=\"control-label\">Periodo</label>\n                        <el-select v-model=\"form.period\"\n                                   @change=\"changePeriod\">\n                            <el-option key=\"month\"\n                                       label=\"Por mes\"\n                                       value=\"month\"></el-option>\n                            <el-option key=\"between_months\"\n                                       label=\"Entre meses\"\n                                       value=\"between_months\"></el-option>\n                            <el-option key=\"date\"\n                                       label=\"Por fecha\"\n                                       value=\"date\"></el-option>\n                            <el-option key=\"between_dates\"\n                                       label=\"Entre fechas\"\n                                       value=\"between_dates\"></el-option>\n                        </el-select>\n                    </div>\n                    <template v-if=\"form.period === 'month' || form.period === 'between_months'\">\n                        <div class=\"col-md-3 form-modern\">\n                            <label class=\"control-label\">Mes de</label>\n                            <el-date-picker v-model=\"form.month_start\"\n                                            :clearable=\"false\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"\n                                            @change=\"changeDisabledMonths\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_months'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Mes al</label>\n                            <el-date-picker v-model=\"form.month_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsMonths\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'date' || form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha del</label>\n                            <el-date-picker v-model=\"form.date_start\"\n                                            :clearable=\"false\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"\n                                            @change=\"changeDisabledDates\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha al</label>\n                            <el-date-picker v-model=\"form.date_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsDates\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"></el-date-picker>\n                        </div>\n                    </template>\n\n                    <div :class=\"betweenDatePicker ? 'col-md-3' : 'col-md-6'\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Sucursal</label>\n                            <el-select v-model=\"form.establishment_id\"\n                                       clearable>\n                                <el-option v-for=\"option in establishments\"\n                                           :key=\"option.id\"\n                                           :label=\"option.name\"\n                                           :value=\"option.id\"></el-option>\n                            </el-select>\n                        </div>\n                    </div>\n                    <div v-show=\"resource == 'reports/sales' || resource == 'reports/purchases'|| resource == 'reports/fixed-asset-purchases'\"\n                         class=\"col-md-3\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Tipo de documento</label>\n                            <el-select v-model=\"form.document_type_id\"\n                                       clearable>\n                                <el-option v-for=\"option in document_types\"\n                                           :key=\"option.id\"\n                                           :label=\"option.description\"\n                                           :value=\"option.id\"></el-option>\n                            </el-select>\n                        </div>\n                    </div>\n\n                    <div v-if=\"resource == 'reports/sales' || resource == 'reports/purchases'|| resource == 'reports/fixed-asset-purchases'\"\n                         class=\"col-lg-5 col-md-5\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">\n                                {{ (resource == 'reports/sales') ? 'Clientes' : 'Proveedores' }}\n                            </label>\n\n                            <el-select v-model=\"form.person_id\"\n                                       :loading=\"loading_search\"\n                                       :remote-method=\"searchRemotePersons\"\n                                       clearable\n                                       filterable\n                                       placeholder=\"Nombre o número de documento\"\n                                       popper-class=\"el-select-customers\"\n                                       remote\n                                       @change=\"changePersons\">\n                                <el-option v-for=\"option in persons\"\n                                           :key=\"option.id\"\n                                           :label=\"option.description\"\n                                           :value=\"option.id\"></el-option>\n                            </el-select>\n\n                        </div>\n                    </div>\n\n                    <template v-if=\"users.length  < 1\">\n                        <div v-if=\"applyCustomer\"\n                             :class=\"(\n                             resource == 'reports/commissions' ||\n                             resource == 'reports/sales' ||\n                             resource == 'reports/purchases') ? 'col-lg-4 col-md-4':'col-lg-3 col-md-3'\">\n                            <div class=\"form-group\">\n                                <label class=\"control-label\">\n                                    Usuarios\n                                </label>\n\n                                <el-select v-model=\"form.seller_id\"\n                                           clearable\n                                           filterable\n                                           placeholder=\"Nombre usuario\"\n                                           popper-class=\"el-select-customers\">\n                                    <el-option v-for=\"option in sellers\"\n                                               :key=\"option.id\"\n                                               :label=\"option.name\"\n                                               :value=\"option.id\"></el-option>\n                                </el-select>\n\n                            </div>\n                        </div>\n                    </template>\n                    <template v-else>\n                        <div class=\"col-md-2 form-group\">\n                            <label class=\"control-label\">Tipo de usuario</label>\n                            <el-select v-model=\"form.user_type\"\n                                       clearable\n                                       @change=\"ChangedSalesnote\">\n                                <el-option key=\"CREADOR\"\n                                           label=\"Registrado por\"\n                                           value=\"CREADOR\"></el-option>\n                                <el-option v-show=\"form.document_type_id !== '80'\"\n                                           key=\"VENDEDOR\"\n                                           label=\"Vendedor asignado\"\n                                           value=\"VENDEDOR\"></el-option>\n                            </el-select>\n                        </div>\n                        <div class=\"col-md-2 form-group\">\n                            <label class=\"control-label\">{{\n                                    form.user_type === 'CREADOR' ? 'Usuario' : 'Vendedor'\n                                                         }}</label>\n                            <el-select v-model=\"form.user_id\"\n                                       :disabled=\"cantChoiseUserWithUserType\"\n                                       clearable\n                                       filterable\n                                       multiple>\n                                <el-option v-for=\"user in users\"\n                                           :key=\"user.id\"\n                                           :label=\"user.name\"\n                                           :value=\"user.id\"></el-option>\n                            </el-select>\n                        </div>\n                    </template>\n                   \n\n                   \n\n                    <div class=\"col-md-6\" v-if=\"resource == 'reports/commissions-detail'\">\n                            <div class=\"form-group\">\n                                <label class=\"control-label\">Productos\n                                </label>\n\n                                <el-select v-model=\"form.item_id\" filterable remote popper-class=\"el-select-customers\"  clearable\n                                    placeholder=\"Código interno o nombre\"\n                                    :remote-method=\"searchRemoteItems\"\n                                    :loading=\"loading_search_items\" >\n                                    <el-option v-for=\"option in items\" :key=\"option.id\" :value=\"option.id\" :label=\"option.description\"></el-option>\n                                </el-select>\n\n                            </div>\n                    </div>\n\n\n                    <div class=\"col-md-6\" v-if=\"resource == 'reports/commissions-detail'\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Categoría\n                            </label>\n\n                            <el-select v-model=\"form.category_id\" filterable remote popper-class=\"el-select-customers\"  clearable\n                                placeholder=\"Nombre\"\n                                :remote-method=\"searchRemoteCategories\"\n                                :loading=\"loading_search_categories\" >\n                                <el-option v-for=\"option in categories\" :key=\"option.id\" :value=\"option.id\" :label=\"option.name\"></el-option>\n                            </el-select>\n\n                        </div>\n                    </div>\n\n                    <div class=\"col-lg-7 col-md-7 col-md-7 col-sm-12 mt-3\">\n                        <el-button :loading=\"loading_submit\"\n                                   class=\"submit\"\n                                   icon=\"el-icon-search\"\n                                   type=\"primary\"\n                                   @click.prevent=\"getRecordsByFilter\">Buscar\n                        </el-button>\n\n                        <template v-if=\"records.length>0 && resource  !== 'reports/document-detractions'\">\n\n                            <el-button class=\"submit\"\n                                       icon=\"el-icon-tickets\"\n                                       type=\"danger\"\n                                       @click.prevent=\"clickDownload('pdf')\">Exportar PDF\n                            </el-button>\n\n                            <el-button class=\"submit\"\n                                       type=\"success\"\n                                       @click.prevent=\"clickDownload('excel')\"><i class=\"fa fa-file-excel\"></i> Exportal\n                                                                                                                Excel\n                            </el-button>\n\n                        </template>\n\n                    </div>\n\n                </div>\n                <div class=\"row mt-1 mb-4\">\n\n                </div>\n            </div>\n\n\n            <div class=\"col-md-12\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                        <thead>\n                        <slot name=\"heading\"></slot>\n                        </thead>\n                        <tbody>\n                        <slot v-for=\"(row, index) in records\"\n                              :index=\"customIndex(index)\"\n                              :row=\"row\"></slot>\n                        </tbody>\n                        <tfoot>\n                            <template>\n                                <tr>\n                                    <td class=\"text-right\" colspan=\"10\">TOTAL:</td>\n                                    <td class=\"text-center\">{{ totals.acum_unit_gain}}</td>\n                                     <td class=\"text-center\">{{ totals.acum_overall_profit}}</td>\n                                </tr>\n\n                            </template>\n                            \n                        </tfoot>\n                    </table>\n                    <div>\n                        <!--<el-pagination\n                            :current-page.sync=\"pagination.current_page\"\n                            :page-size=\"pagination.per_page\"\n                            :total=\"pagination.total\"\n                            layout=\"total, prev, pager, next\"\n                            @current-change=\"getRecords\">\n                        </el-pagination>-->\n                    </div>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</template>\n<style>\n.font-custom {\n    font-size: 15px !important\n}\n</style>\n<script>\n\nimport moment from 'moment'\nimport queryString from 'query-string'\n\nexport default {\n    props: {\n        resource: String,\n        applyCustomer: {\n            type: Boolean,\n            required: false,\n            default: false\n        },\n        visibleColumns: Object\n    },\n    data() {\n        return {\n            isVisible: false,\n            loading_submit: false,\n            persons: [],\n            all_persons: [],\n            loading_search: false,\n            columns: [],\n            records: [],\n            headers: headers_token,\n            document_types: [],\n            pagination: {},\n            search: {},\n            totals: {},\n            establishment: null,\n            establishments: [],\n            web_platforms: [],\n            state_types: [],\n            users: [],\n            form: {\n                document_type_id: null,\n                user_type: null,\n                user_id: [],\n            },\n            pickerOptionsDates: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM-DD')\n                    return this.form.date_start > time\n                }\n            },\n            pickerOptionsMonths: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM')\n                    return this.form.month_start > time\n                }\n            },\n            sellers: [],\n            items: [],\n            all_items: [],\n            loading_search_items: false,\n            categories: [],\n            all_categories: [],\n            loading_search_categories: false,\n            showLeftShadow: false,\n            showRightShadow: false,\n        }\n    },\n    computed: {\n        cantChoiseUserWithUserType(){\n            if(this.form.user_type && this.form.user_type.length > 1) return false;\n            return true;\n        },\n        betweenDatePicker()\n        {\n            return ['between_dates', 'between_months'].includes(this.form.period)\n        }\n    },\n    created() {\n        this.initForm()\n        this.initTotals()\n        this.$eventHub.$on('reloadData', () => {\n            this.getRecords()\n        })\n    },\n    async mounted() {\n\n        await this.$http.get(`/${this.resource}/filter`)\n            .then(response => {\n                this.establishments = response.data.establishments;\n                this.all_persons = response.data.persons\n                this.all_categories = response.data.categories\n                this.document_types = response.data.document_types;\n                this.sellers = response.data.sellers\n                this.state_types = response.data.state_types\n                this.web_platforms = response.data.web_platforms\n                // this.form.establishment_id = (this.establishments.length > 0)?this.establishments[0].id:null;\n                if(response.data.users !== undefined) {\n                    this.users = response.data.users;\n                }\n\n                this.filterCategories()\n            });\n\n\n        await this.filterPersons()\n        // await this.getTotals()\n        this.form.type_person = this.resource === 'reports/sales' ? 'customers' : 'suppliers'\n\n        this.$nextTick(() => {\n            const el = this.$refs.scrollContainer;\n            if (el) {\n                el.addEventListener('scroll', this.checkScrollShadows);\n                this.checkScrollShadows();\n            }\n        });\n\n    },\n    methods: {\n        checkScrollShadows() {\n            const el = this.$refs.scrollContainer;\n            if (!el) return;\n            \n            const scrollLeft = el.scrollLeft;\n            const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n            \n            this.showLeftShadow = scrollLeft > 1;\n            this.showRightShadow = scrollRight > 1;\n        },\n        toggleInformation(){\n            this.isVisible = !this.isVisible;\n        },\n        ChangedSalesnote(){\n            if(this.form.document_type_id == '80' && this.form.user_type != null ){\n                this.form.user_type = 'CREADOR';\n            }\n\n\n            this.form.person_id = null\n            this.form.user_id = [];\n            this.$eventHub.$emit('changeFilterColumn', 'seller')\n        },\n        changePersons() {\n            // this.form.type_person = this.resource === 'reports/sales' ? 'customers':'suppliers'\n        },\n        searchRemotePersons(input) {\n\n            if (input.length > 0) {\n\n                this.loading_search = true\n                let parameters = `input=${input}`\n\n                this.form.type_person = this.resource === 'reports/sales' ? 'customers' : 'suppliers'\n\n\n                this.$http.get(`/reports/data-table/persons/${this.form.type_person}?${parameters}`)\n                    .then(response => {\n                        this.persons = response.data.persons\n                        this.loading_search = false\n\n                        if (this.persons.length == 0) {\n                            this.filterPersons()\n                        }\n                    })\n            } else {\n                this.filterPersons()\n            }\n\n        },\n        filterPersons() {\n            this.persons = this.all_persons\n        },\n        getTotals(records) {\n\n            this.initTotals()\n\n            this.totals.acum_unit_gain = records.reduce((accum,item) => accum + Number(item.unit_gain), 0).toFixed(2)\n            this.totals.acum_overall_profit = records.reduce((accum,item) => accum + Number(item.overall_profit), 0).toFixed(2)\n            \n        },\n        clickDownload(type) {\n            let query = queryString.stringify({\n                ...this.form\n            });\n            delete(query.user_id)\n            delete(query.document_type_id)\n\n            window.open(`/${this.resource}/${type}/?${query}&user_id=${JSON.stringify(this.form.user_id)}&document_type_id=${JSON.stringify(this.form.document_type_id)}`, '_blank');\n        },\n\n        initForm() {\n\n            this.form = {\n                establishment_id: null,\n                person_id: null,\n                type_person: null,\n                document_type_id: null,\n                period: 'month',\n                date_start: moment().format('YYYY-MM-DD'),\n                date_end: moment().format('YYYY-MM-DD'),\n                month_start: moment().format('YYYY-MM'),\n                month_end: moment().format('YYYY-MM'),\n                seller_id: null,\n                state_type_id: null,\n                include_categories: false,\n                guides: null,\n                user_type: null,\n                user_id: [],\n                item_id: null,\n                category_id: null,\n            }\n\n        },\n        initTotals() {\n\n            this.totals = {\n                acum_unit_gain: 0,\n                acum_overall_profit: 0,\n            }\n        },\n        customIndex(index) {\n            return index + 1\n        },\n        async getRecordsByFilter() {\n\n            this.loading_submit = true\n            await this.getRecords()\n            this.loading_submit = false\n\n        },\n        getRecords() {\n            /*if(!this.form.item_id) {\n                this.$message.warning('Debe seleccionar un producto');\n            }*/\n\n            return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n                this.records = response.data.data\n                //this.pagination = response.data.meta\n                //this.pagination.per_page = parseInt(response.data.meta.per_page)\n                //this.loading_submit = false\n                // this.initTotals()\n                 this.getTotals(response.data.data)\n            });\n\n\n        },\n        getQueryParameters() {\n            if(this.users.length  > 0){\n                // delete(this.form.type_person)\n            }\n            let parameters = queryString.stringify({\n                page: this.pagination.current_page,\n                limit: this.limit,\n                ...this.form\n            })\n            delete(parameters.user_id)\n            delete(parameters.document_type_id)\n\n            return `${parameters}&user_id=${JSON.stringify(this.form.user_id)}&document_type_id=${JSON.stringify(this.form.document_type_id)}`\n\n        },\n\n        changeDisabledDates() {\n            if (this.form.date_end < this.form.date_start) {\n                this.form.date_end = this.form.date_start\n            }\n            // this.loadAll();\n        },\n        changeDisabledMonths() {\n            if (this.form.month_end < this.form.month_start) {\n                this.form.month_end = this.form.month_start\n            }\n            // this.loadAll();\n        },\n        changePeriod() {\n            if (this.form.period === 'month') {\n                this.form.month_start = moment().format('YYYY-MM');\n                this.form.month_end = moment().format('YYYY-MM');\n            }\n            if (this.form.period === 'between_months') {\n                this.form.month_start = moment().startOf('year').format('YYYY-MM'); //'2019-01';\n                this.form.month_end = moment().endOf('year').format('YYYY-MM');\n\n            }\n            if (this.form.period === 'date') {\n                this.form.date_start = moment().format('YYYY-MM-DD');\n                this.form.date_end = moment().format('YYYY-MM-DD');\n            }\n            if (this.form.period === 'between_dates') {\n                this.form.date_start = moment().startOf('month').format('YYYY-MM-DD');\n                this.form.date_end = moment().endOf('month').format('YYYY-MM-DD');\n            }\n            // this.loadAll();\n        },\n        searchRemoteItems(input) {\n                if (input.length > 0) {\n\n                    this.loading_search = true\n                    let parameters = `input=${input}`\n\n\n                    this.$http.get(`/reports/data-table/items/?${parameters}`)\n                            .then(response => {\n                                this.items = response.data.items\n                                this.loading_search = false\n\n                                if(this.items.length == 0){\n                                    this.filterItems()\n                                }\n                            })\n                } else {\n                    this.filterItems()\n                }\n\n        },\n        filterItems() {\n            this.items = this.all_items\n        },\n        searchRemoteCategories(input) \n        {\n            if (input.length > 0) \n            {\n                this.loading_search_categories = true\n\n                this.$http.get(`/categories/search-data?input=${input}`)\n                        .then(response => {\n                            this.categories = response.data\n                            this.loading_search_categories = false\n                            if(this.categories.length == 0)this.filterCategories()\n                        })\n            } \n            else \n            {\n                this.filterCategories()\n            }\n        },\n        filterCategories() \n        {\n            this.categories = this.all_categories\n        },\n    }\n}\n</script>\n"],"sourceRoot":""}]);
// Exports
export default ___CSS_LOADER_EXPORT___;
