e\n                                       @change=\"changePersons\">\n                                <el-option v-for=\"option in items\"\n                                           :key=\"option.id\"\n                                           :label=\"option.description\"\n                                           :value=\"option.id\"></el-option>\n                            </el-select>\n\n                        </div>\n                    </div>\n                    <div class=\"col-md-3 form-modern\">\n                        <label class=\"control-label\">Fecha de envio</label>\n                        <el-select v-model=\"form.period\"\n                                   @change=\"changePeriod\">\n                            <el-option key=\"month\"\n                                       label=\"Por mes\"\n                                       value=\"month\"></el-option>\n                            <el-option key=\"between_months\"\n                                       label=\"Entre meses\"\n                                       value=\"between_months\"></el-option>\n                            <el-option key=\"date\"\n                                       label=\"Por fecha\"\n                                       value=\"date\"></el-option>\n                            <el-option key=\"between_dates\"\n                                       label=\"Entre fechas\"\n                                       value=\"between_dates\"></el-option>\n                        </el-select>\n                    </div>\n                    <template v-if=\"form.period === 'month' || form.period === 'between_months'\">\n                        <div class=\"col-md-3 form-modern\">\n                            <label class=\"control-label\">Mes de</label>\n                            <el-date-picker v-model=\"form.month_start\"\n                                            :clearable=\"false\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"\n                                            @change=\"changeDisabledMonths\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_months'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Mes al</label>\n                            <el-date-picker v-model=\"form.month_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsMonths\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'date' || form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha del</label>\n                            <el-date-picker v-model=\"form.date_start\"\n                                            :clearable=\"false\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"\n                                            @change=\"changeDisabledDates\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha al</label>\n                            <el-date-picker v-model=\"form.date_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsDates\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"></el-date-picker>\n                        </div>\n                    </template>\n\n\n                    <div class=\"col-md-3\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Sucursal</label>\n                            <el-select v-model=\"form.establishment_id\"\n                                       clearable>\n                                <el-option v-for=\"option in establishments\"\n                                           :key=\"option.id\"\n                                           :label=\"option.description\"\n                                           :value=\"option.id\"></el-option>\n                            </el-select>\n                        </div>\n                    </div>\n                    <!--\n                       <div class=\"col-md-3\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Plataforma</label>\n                            <el-select v-model=\"form.web_platform_id\" clearable>\n                                <el-option v-for=\"option in web_platforms\" :key=\"option.id\" :value=\"option.id\" :label=\"option.name\"></el-option>\n                            </el-select>\n                        </div>\n                    </div>\n                    <div class=\"col-md-3\" >\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Tipo de documento</label>\n                            <el-select v-model=\"form.document_type_id\" clearable>\n                                <el-option v-for=\"option in document_types\" :key=\"option.id\" :value=\"option.id\" :label=\"option.description\"></el-option>\n                            </el-select>\n                        </div>\n                    </div> -->\n                    <div class=\"col-lg-2 col-md-2\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\" style=\"width: 100%;\">\n                                &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n                            </label>\n                            <el-checkbox\n                                v-model=\"filter_range\"\n                            >\n                                Filtra por numeración\n                            </el-checkbox>\n                        </div>\n                    </div>\n\n                    <!-- Minimo -->\n                    <div class=\"col-lg-2 col-md-2\" v-if=\"filter_range\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Desde número\n                            </label>\n                            <el-input-number v-model=\"form.min\"\n                                             :min=\"0\"\n                                             :precision=\"0\"\n                                             :step=\"1\"></el-input-number>\n                        </div>\n                    </div>\n                    <!-- Minimo -->\n                    <div class=\"col-lg-2 col-md-2\" v-if=\"filter_range\">\n                        <div class=\"form-group\">\n                            <label class=\"control-label\">Hasta número\n                            </label>\n                            <el-input-number v-model=\"form.max\"\n                                             :min=\"0\"\n                                             :precision=\"0\"\n                                             :step=\"1\"></el-input-number>\n                        </div>\n                    </div>\n\n\n\n                    <div class=\"col-md-12 col-12\">&nbsp;</div>\n                    <div class=\"col-lg-7 col-md-7 col-md-7 col-sm-12\"\n                         style=\"margin-top:29px\">\n                        <el-button :loading=\"loading_submit\"\n                                   class=\"submit\"\n                                   icon=\"el-icon-search\"\n                                   type=\"primary\"\n                                   @click.prevent=\"getRecordsByFilter\">Buscar\n                        </el-button>\n\n                        <template v-if=\"records.length>0\">\n                            <el-button class=\"submit\"\n                                       type=\"success\"\n                                       @click.prevent=\"clickDownload('excel')\"><i\n                                class=\"fa fa-file-excel\"></i> Exportal Excel\n                            </el-button>\n                            <el-button class=\"submit\"\n                                       icon=\"el-icon-tickets\"\n                                       type=\"danger\"\n                                       @click.prevent=\"clickDownload('pdf')\">Exportar PDF\n                            </el-button>\n                            <el-button class=\"submit\"\n                                       icon=\"el-icon-search\"\n                                       type=\"success\"\n                                       @click.prevent=\"clickTotalByItem()\">Ver totales por producto\n                            </el-button>\n                        </template>\n                    </div>\n                </div>\n                <div class=\"row mt-1 mb-4\">\n\n                </div>\n            </div>\n\n\n            <div class=\"col-md-12\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                        <thead>\n                        <slot name=\"heading\"></slot>\n                        </thead>\n                        <tbody>\n                        <slot v-for=\"(row, index) in records\"\n                              :index=\"customIndex(index)\"\n                              :row=\"row\"></slot>\n                        </tbody>\n                    </table>\n                    <div>\n                        <el-pagination\n                            :current-page.sync=\"pagination.current_page\"\n                            :page-size=\"pagination.per_page\"\n                            :total=\"pagination.total\"\n                            layout=\"total, prev, pager, next\"\n                            @current-change=\"getRecords\">\n                        </el-pagination>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <totals-by-item-form\n            :parameters=\"getQueryParameters()\"\n            :resource=\"'reports/guides'\"\n            :showDialog.sync=\"showDialog\"\n        ></totals-by-item-form>\n    </div>\n</template>\n<style>\n.font-custom {\n    font-size: 15px !important\n}\n</style>\n<script>\n\nimport moment from 'moment'\nimport queryString from 'query-string'\n// modules/Report/Resources/assets/js/components/partials/totals_by_item.vue\n// modules/Report/Resources/assets/js/components/DataTableGuide.vue\nimport TotalsByItemForm from '../../../components/partials/totals_by_item.vue'\n\nexport default {\n    components: {TotalsByItemForm},\n    props: {\n        resource: String,\n    },\n    data() {\n        return {\n            isVisible: false,\n            filter_range:false,\n            showDialog: false,\n            loading_submit: false,\n            items: [],\n            all_items: [],\n            loading_search: false,\n            columns: [],\n            records: [],\n            headers: headers_token,\n            document_types: [],\n            pagination: {},\n            search: {},\n            totals: {},\n            establishment: null,\n            establishments: [],\n            web_platforms: [],\n            customers: {},\n            users: {},\n            form: {\n                min: 1,\n                max: 2,\n            },\n            pickerOptionsDates: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM-DD')\n                    return this.form.date_start > time\n                }\n            },\n            pickerOptionsMonths: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM')\n                    return this.form.month_start > time\n                }\n            },\n            showLeftShadow: false,\n            showRightShadow: false,\n        }\n    },\n    computed: {},\n    created() {\n        this.initForm()\n        this.initTotals()\n        this.$eventHub.$on('reloadData', () => {\n            this.getRecords()\n        })\n    },\n    async mounted() {\n\n        await this.$http.post(`/${this.resource}/filter`)\n            .then(response => {\n                this.establishments = response.data.establishments;\n                this.all_items = response.data.items\n                this.document_types = response.data.document_types;\n                this.web_platforms = response.data.web_platforms\n                this.customers = response.data.customers\n                this.users = response.data.users\n            });\n\n\n        await this.filterItems()\n\n        this.$nextTick(() => {\n            const el = this.$refs.scrollContainer;\n            if (el) {\n                el.addEventListener('scroll', this.checkScrollShadows);\n                this.checkScrollShadows();\n            }\n        });\n\n    },\n    methods: {\n        checkScrollShadows() {\n            const el = this.$refs.scrollContainer;\n            if (!el) return;\n            \n            const scrollLeft = el.scrollLeft;\n            const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n            \n            this.showLeftShadow = scrollLeft > 1;\n            this.showRightShadow = scrollRight > 1;\n        },\n        toggleInformation(){\n            this.isVisible = !this.isVisible;\n        },\n        clickTotalByItem() {\n            this.showDialog = true\n        },\n        changePersons() {\n            // this.form.type_person = 'customers'\n        },\n        searchRemoteCustomers(input) {\n            if (input.length > 0) {\n                this.loading_search = true\n                let parameters = `input=${input}`\n                this.$http.post(`/${this.resource}/customers`, {id: parameters})\n                    .then(response => {\n                        console.error(resposne)/*\n                                this.items = response.data.items\n                                this.loading_search = false\n                                if(this.items.length == 0){\n                                    this.filterItems()\n                                }*/\n                    })\n            } else {\n                this.filterItems()\n            }\n\n        },\n        searchRemoteUsers(input) {\n            if (input.length > 0) {\n                this.loading_search = true\n                let parameters = `input=${input}`\n                this.$http.post(`/${this.resource}/users`, {id: parameters})\n                    .then(response => {\n                        console.error(resposne)/*\n                                this.items = response.data.items\n                                this.loading_search = false\n                                if(this.items.length == 0){\n                                    this.filterItems()\n                                }*/\n                    })\n            } else {\n                this.filterItems()\n            }\n\n        },\n        searchRemoteItems(input) {\n            if (input.length > 0) {\n                this.loading_search = true\n                let parameters = `input=${input}`\n                this.$http.get(`/reports/data-table/items/?${parameters}`)\n                    .then(response => {\n                        this.items = response.data.items\n                        this.loading_search = false\n                        if (this.items.length == 0) {\n                            this.filterItems()\n                        }\n                    })\n            } else {\n                this.filterItems()\n            }\n\n        },\n        filterItems() {\n            this.items = this.all_items\n        },\n        clickDownload(type) {\n            let query = queryString.stringify({\n                ...this.form\n            });\n            window.open(`/${this.resource}/${type}/?${query}`, '_blank');\n        },\n        initForm() {\n\n            this.form = {\n                establishment_id: null,\n                customer_id: null,\n                item_id: null,\n                user_id: null,\n                document_type_id: null,\n                period: 'month',\n                date_start: moment().format('YYYY-MM-DD'),\n                date_end: moment().format('YYYY-MM-DD'),\n                month_start: moment().format('YYYY-MM'),\n                month_end: moment().format('YYYY-MM'),\n            }\n\n        },\n        initTotals() {\n\n            this.totals = {\n                acum_total_taxed: 0,\n                acum_total_igv: 0,\n                acum_total: 0,\n                acum_total_exonerated: 0,\n                acum_total_unaffected: 0,\n                acum_total_free: 0,\n\n                acum_total_taxed_usd: 0,\n                acum_total_igv_usd: 0,\n                acum_total_usd: 0,\n            }\n        },\n        customIndex(index) {\n            return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n        },\n        async getRecordsByFilter() {\n            /*\n                          if(!this.form.item_id){\n                              return this.$message.error('Debe seleccionar un producto')\n                          }\n          */\n            this.loading_submit = await true\n            await this.getRecords()\n            this.loading_submit = await false\n\n        },\n        getRecords() {\n            let url = `/${this.resource}/records?${this.getQueryParameters()}`;\n            return this.$http.get(url).then((response) => {\n                this.records = response.data.data\n                this.pagination = response.data.meta\n                this.pagination.per_page = parseInt(response.data.meta.per_page)\n                this.loading_submit = false\n                // this.initTotals()\n                if (this.resource == 'reports/sales') this.getTotals(response.data.data)\n            });\n\n\n        },\n        getQueryParameters() {\n            let param = {\n                page: this.pagination.current_page,\n                limit: this.limit,\n                ...this.form\n            };\n            if(this.filter_range === false) {\n                delete param.min;\n                delete param.max;\n            }\n            return queryString.stringify(param)\n        },\n\n        changeDisabledDates() {\n            if (this.form.date_end < this.form.date_start) {\n                this.form.date_end = this.form.date_start\n            }\n            // this.loadAll();\n        },\n        changeDisabledMonths() {\n            if (this.form.month_end < this.form.month_start) {\n                this.form.month_end = this.form.month_start\n            }\n            // this.loadAll();\n        },\n        changePeriod() {\n            if (this.form.period === 'month') {\n                this.form.month_start = moment().format('YYYY-MM');\n                this.form.month_end = moment().format('YYYY-MM');\n            }\n            if (this.form.period === 'between_months') {\n                this.form.month_start = moment().startOf('year').format('YYYY-MM'); //'2019-01';\n                this.form.month_end = moment().endOf('year').format('YYYY-MM');\n\n            }\n            if (this.form.period === 'date') {\n                this.form.date_start = moment().format('YYYY-MM-DD');\n                this.form.date_end = moment().format('YYYY-MM-DD');\n            }\n            if (this.form.period === 'between_dates') {\n                this.form.date_start = moment().startOf('month').format('YYYY-MM-DD');\n                this.form.date_end = moment().endOf('month').format('YYYY-MM-DD');\n            }\n            // this.loadAll();\n        },\n    }\n}\n</script>\n"],"sourceRoot":""}]);
