<template>
    <div>
        <div class="page-header pr-0">
            <h2>
                <a href="/list-reports">
                    <svg
                        xmlns="http://www.w3.org/2000/svg"
                        style="margin-top: -5px;"
                        width="24"
                        height="24"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        stroke-width="2"
                        stroke-linecap="round"
                        stroke-linejoin="round"
                        class="icon icon-tabler icons-tabler-outline icon-tabler-file-analytics"
                    >
                        <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                        <path d="M14 3v4a1 1 0 0 0 1 1h4" />
                        <path
                            d="M17 21h-10a2 2 0 0 1 -2 -2v-14a2 2 0 0 1 2 -2h7l5 5v11a2 2 0 0 1 -2 2z"
                        />
                        <path d="M9 17l0 -5" />
                        <path d="M12 17l0 -1" />
                        <path d="M15 17l0 -3" />
                    </svg>
                </a>
            </h2>
            <ol class="breadcrumbs">
                <li class="active">
                    <span> R. General por cliente/vendedor </span>
                </li>
            </ol>
        </div>
        <div class="card mb-0 pt-2 pt-md-0 tab-content-default row-new">
            <!-- <div class="card-header bg-info">
                <h3 class="my-0">R. General por cliente/vendedor</h3>
            </div> -->
            <div class="card mb-0">
                <div class="card-body">
                    <data-table :resource="resource">
                        <tr slot="heading">
                            <!-- <th class="">#</th> -->
                            <th class="text-left">F. Emisión</th>
                            <th class="text-left">F. Entrega</th>
                            <th class="text-left">N° Pedido</th>
                            <th
                                class="text-left"
                                v-if="columns.customer.visible"
                            >
                                Cliente
                            </th>
                            <th class="text-left" v-if="columns.user.visible">
                                Vendedor
                            </th>
                            <th class="text-center">Monto</th>
                            <th class="text-center">Estado</th>
                        </tr>

                        <tr></tr>
                        <tr slot-scope="{ index, row }">
                            <!-- <td>{{ index }}</td>  -->
                            <td class="text-left">
                                {{ formatDate(row.date_of_issue) }}
                            </td>
                            <td class="text-left">
                                {{ formatDate(row.delivery_date) }}
                            </td>
                            <td class="text-left">{{ row.number_full }}</td>
                            <td v-if="columns.customer.visible">
                                {{ row.customer_name }}<br /><small
                                    v-text="row.customer_number"
                                ></small>
                            </td>
                            <td class="text-left" v-if="columns.user.visible">
                                {{ row.user_name }}
                            </td>
                            <td class="text-center">{{ row.total }}</td>
                            <td class="text-center">
                                {{ row.state_description }}
                            </td>
                        </tr>
                    </data-table>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataTable from "../../components/DataTableOrderNotesConsolidated.vue";

export default {
    components: { DataTable },
    data() {
        return {
            resource: "reports/order-notes-general",
            form: {},
            columns: {
                customer: {
                    visible: false
                },
                user: {
                    visible: false
                }
            }
        };
    },
    async created() {
        this.$eventHub.$on("changeFilterColumn", type => {
            this.changeVisibleColumn(type);
        });
    },
    methods: {
        formatDate(date) {
            if (!date) return null;
            const parsedDate = moment(date);
            return parsedDate.isValid()
                ? parsedDate.format("DD-MM-YYYY")
                : null;
        },
        changeVisibleColumn(type) {
            switch (type) {
                case "person":
                    this.columns.user.visible = true;
                    this.columns.customer.visible = false;
                    break;

                case "seller":
                    this.columns.customer.visible = true;
                    this.columns.user.visible = false;
                    break;
            }
        }
    }
};
</script>
