 url: `/${this.resource}/export`,\n                method: 'POST',\n                data: {\n                    'format': format,\n                    columns: JSON.stringify(this.visibleColumns),\n                    ...this.form\n                },\n            })\n                .then(response => {\n                    let res = response.data;\n                    if (res.success) {\n                        // this.$message.success(res.message);\n                        \n                        this.$notify({\n                            message: res.message,\n                            type: 'success',\n                            onClick: ()=>{\n                                window.open('/reports/download-tray')\n                            }\n                        })\n                    } else {\n                        this.$message.error('Error al exportar');\n                    }\n                })\n                .catch(error => {\n                    console.log(error);\n                    this.errors = error;\n                })\n                .then(() => {\n                    this.loadingPdf = false;\n                    this.loadingXlsx = false;\n                    this.loading = false;\n                });\n\n        }\n    }\n}\n</script>\n"],"sourceRoot":""}]);
